ROLE_MAX_SCORES = {23059: 29, 23060: 31, 23061: 30, 23062: 26, 23063: 38, 23064: 40, 23065: 40, 23066: 29, 23067: 29, 23068: 14, 23069: 30, 23071: 29, 23072: 44, 23073: 55, 23074: 32, 23075: 53, 23076: 29, 23077: 49, 23078: 36, 23079: 53}


def get_public_questions() -> List[Dict[str, Any]]:

    """
    Returns the 30 quiz questions for public frontend display,
    omitting internal role_ids from options to prevent client-side manipulation.
    """
    public_q = []
    for q in QUIZ_QUESTIONS:
        sec_info = SECTION_METADATA.get(q["section"], {"title_th": q["section"], "desc": ""})
        options = [
            {
                "id": opt["id"],
                "text": opt["text"],
            }
            for opt in q["options"]
        ]
        public_q.append({
            "id": q["id"],
            "section": q["section"],
            "section_th": sec_info["title_th"],
            "section_desc": sec_info["desc"],
            "question": q["question"],
            "is_multiple": q["is_multiple"],
            "options": options
        })
    return public_q


def evaluate_quiz(user_answers: Dict[str, Any]) -> Dict[str, Any]:
    """
    Evaluates the 30 answers against the BCS Tech Career Quiz mapping.
    
    Tie-Breaker Rule:
    1. Highest total role score.
    2. Sum of scores from Skills (Q7-Q12) and Abilities (Q13-Q21).
    3. Stable Role ID sorting.
    
    Returns top 3 matching roles along with full ranked breakdown.
    """
    role_scores = {rid: 0 for rid in ROLES_METADATA}
    skills_abilities_scores = {rid: 0 for rid in ROLES_METADATA}

    q_map = {q["id"]: q for q in QUIZ_QUESTIONS}

    for q_id, q in q_map.items():
        ans_val = user_answers.get(str(q_id))
        if ans_val is None:
            ans_val = user_answers.get(q_id)
        if ans_val is None:
            continue

        if q["is_multiple"]:
            # Expecting a list of option IDs
            selected_ids = ans_val if isinstance(ans_val, list) else [ans_val]
            for opt_id in selected_ids:
                try:
                    opt_idx = int(opt_id)
                    if 0 <= opt_idx < len(q["options"]):
                        for rid in q["options"][opt_idx]["role_ids"]:
                            if rid in role_scores:
                                role_scores[rid] += 1
                except (ValueError, TypeError):
                    continue
        else:
            # Single option ID
            try:
                opt_idx = int(ans_val)
                if 0 <= opt_idx < len(q["options"]):
                    for rid in q["options"][opt_idx]["role_ids"]:
                        if rid in role_scores:
                            role_scores[rid] += 1
                            if 7 <= q_id <= 21:
                                skills_abilities_scores[rid] += 1
            except (ValueError, TypeError):
                continue

    # Sort roles using tie-breaking criteria
    # 1. Total score (descending)
    # 2. Skills & Abilities subscore (descending)
    # 3. Role ID (ascending)
    sorted_role_ids = sorted(
        ROLES_METADATA.keys(),
        key=lambda rid: (
            -role_scores[rid],
            -skills_abilities_scores[rid],
            rid
        )
    )

    ranked_results = []
    top_score = max(role_scores.values()) if any(role_scores.values()) else 1

    for rank_idx, rid in enumerate(sorted_role_ids, start=1):
        meta = ROLES_METADATA[rid]
        score = role_scores[rid]
        max_possible = ROLE_MAX_SCORES.get(rid, 1)
        match_pct = round((score / max_possible) * 100) if max_possible > 0 else 0
        relative_pct = round((score / top_score) * 100) if top_score > 0 else 0

        ranked_results.append({
            "rank": rank_idx,
            "role_id": rid,
            "title": meta["title"],
            "title_th": meta["title_th"],
            "category": meta["category"],
            "icon": meta["icon"],
            "badge_color": meta["badge_color"],
            "score": score,
            "max_score": max_possible,
            "match_percentage": min(100, match_pct),
            "relative_percentage": min(100, relative_pct),
            "skills_abilities_score": skills_abilities_scores[rid],
            "summary": meta["summary"],
            "description": meta["description"],
            "key_skills": meta["key_skills"],
            "matching_ce_courses": meta["matching_ce_courses"],
            "career_prospects": meta["career_prospects"]
        })

    return {
        "success": True,
        "total_questions": len(QUIZ_QUESTIONS),
        "answered_count": len([k for k, v in user_answers.items() if v is not None and v != []]),
        "top_roles": ranked_results[:3],
        "all_roles": ranked_results
    }
